// Uma linha da planilha por pessoa que entrou.
//
// O payload vem de /api/entrar-live (ver o arquivo para a lista de campos).
// Aqui so achatamos e damos nomes de COLUNA legiveis: o cabecalho da planilha
// tem que bater exatamente com estas chaves.

const linhas = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  const nome = String(b.nome || '').trim();
  const whatsapp = String(b.whatsapp || '');

  // Telefone como TEXTO: sem o apostrofo o Sheets come o '+' e transforma
  // +5511987654321 em notacao cientifica.
  const whatsappCelula = whatsapp ? `'${whatsapp}` : '';

  const origem = [b.utm_source, b.utm_medium, b.utm_campaign, b.utm_content]
    .filter(Boolean)
    .join(' / ');

  linhas.push({
    json: {
      'Data/hora': b.data_hora_entrada || '',
      'Nome': nome,
      'WhatsApp': whatsappCelula,
      'Live': b.evento_titulo || '',
      'Origem': origem,
      'gclid': b.gclid || '',
      'fbclid': b.fbclid || '',
      'lead_id': b.lead_id || '',
    },
  });
}

return linhas;
